 * The two policy kinds a limiter file can declare. Each keeps one
 * independent state per key and exposes the advance/allow/record protocol
 * the simulator drives every policy on a route through for each event.
 */

/**
 * A token bucket. Tokens are tracked as an exact fraction with denominator
 * `per`, stored as a BigInt numerator, so that partial-period refills never
 * lose precision to rounding.
 */
export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.numeratorCap = capacity * per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { numerator: this.numeratorCap, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const grown = state.numerator + this.refill * elapsed
      state.numerator = grown > this.numeratorCap ? this.numeratorCap : grown
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it has recorded for
 * a key, forgetting ticks that have fallen out of the span on each advance.
 */
export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) cut++
    if (cut > 0) state.ticks.splice(0, cut)
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key) {
    // The caller always advances to the current tick before recording, so
    // the state already exists.
    this.states.get(key).ticks.push(this.#lastTick)
  }
}
"}

