{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file's text into its declared policies, routes and
 * events. Throws a `LineError` carrying the 1-based line number and a bare
 * reason string on the first line that fails to parse, per the
 * specification's list of failure messages.
 */

import { isValidToken, parseCount } from './tokens.js'
import { TokenBucket, SlidingWindow } from './policies.js'

export class LineError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

/**
 * @param {string} text the raw file contents read from standard input
 * @returns {{ policies: Map<string, TokenBucket|SlidingWindow>,
 *             routes: Array<{ prefix: string, policies: Array<TokenBucket|SlidingWindow> }>,
 *             events: Array<{ tick: bigint, key: string }> }}
 */
export function parseLimiterFile(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routePrefixes = new Set()
  const routes = []
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    try {
      if (directive === 'bucket') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        parseBucket(words, policies)
      } else if (directive === 'window') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        parseWindow(words, policies)
      } else if (directive === 'route') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        parseRoute(words, policies, routePrefixes, routes)
      } else if (directive === 'event') {
        seenEvent = true
        const tick = parseEvent(words, events)
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${words[1]} is before tick ${lastTick}`)
        }
        lastTick = tick
      } else {
        throw new Error(`unknown directive ${directive}`)
      }
    } catch (error) {
      throw new LineError(lineNumber, error.message)
    }
  }

  return { policies, routes, events }
}

function parseBucket(words, policies) {
  if (words.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
  const [, name, capacityText, refillText, perText] = words
  if (!isValidToken(name)) throw new Error(`invalid policy name ${name}`)
  const capacity = parseCount(capacityText, 'capacity', 1)
  const refill = parseCount(refillText, 'refill', 0)
  const per = parseCount(perText, 'per', 1)
  if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
  policies.set(name, new TokenBucket(name, capacity, refill, per))
}

function parseWindow(words, policies) {
  if (words.length !== 4) throw new Error('expected window <name> <limit> <span>')
  const [, name, limitText, spanText] = words
  if (!isValidToken(name)) throw new Error(`invalid policy name ${name}`)
  const limit = parseCount(limitText, 'limit', 0)
  const span = parseCount(spanText, 'span', 1)
  if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
  policies.set(name, new SlidingWindow(name, limit, span))
}

function parseRoute(words, policies, routePrefixes, routes) {
  if (words.length < 3) throw new Error('expected route <prefix> <policy>...')
  const prefix = words[1]
  if (!isValidToken(prefix)) throw new Error(`invalid route prefix ${prefix}`)
  const policyNames = words.slice(2)
  const routePolicies = []
  for (const name of policyNames) {
    const policy = policies.get(name)
    if (!policy) throw new Error(`unknown policy ${name}`)
    routePolicies.push(policy)
  }
  if (routePrefixes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
  routePrefixes.add(prefix)
  routes.push({ prefix, policies: routePolicies })
}

function parseEvent(words, events) {
  if (words.length !== 3) throw new Error('expected event <tick> <key>')
  const [, tickText, key] = words
  const tick = parseCount(tickText, 'tick', 0)
  if (!isValidToken(key)) throw new Error(`invalid key ${key}`)
  events.push({ tick, key })
  return tick
}
"}

