/** One `<tick> <key> allow|deny <policy>` line per event, in log order. */
export function renderReplay(verdicts) {
  return verdicts
    .map(({ tick, key, allowed, deniedBy }) =>
      allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${deniedBy}`
    )
    .join('')
