 * One `<key> allowed=<a> denied=<d>` line per key that saw an event, in
 * ascending key order, followed by the `total allowed=<a> denied=<d>` line.
 */
export function renderSummary(verdicts) {
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const { key, allowed } of verdicts) {
    let counts = perKey.get(key)
    if (!counts) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
    }
    if (allowed) {
      counts.allowed++
      totalAllowed++
    } else {
      counts.denied++
      totalDenied++
    }
  }

  const lines = []
  for (const key of [...perKey.keys()].sort()) {
    const { allowed, denied } = perKey.get(key)
    lines.push(`${key} allowed=${allowed} denied=${denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}
